function detectOutreachMethod(url3) {
  const u2 = url3.toLowerCase();
  if (u2.includes("instagram.com")) return { platform: "Instagram", method: "dm", instruction: "Send a DM on Instagram" };
  if (u2.includes("tiktok.com")) return { platform: "TikTok", method: "dm", instruction: "Send a DM on TikTok" };
  if (u2.includes("twitter.com") || u2.includes("x.com")) return { platform: "X / Twitter", method: "dm", instruction: "Send a DM on X" };
  if (u2.includes("facebook.com")) return { platform: "Facebook", method: "dm", instruction: "Send a DM on Facebook" };
  return { platform: "Website", method: "email", instruction: "Send an email via their website contact page" };
}
