router11.get("/reviews", async (req, res) => {
  const { businessId } = req.query;
  if (!businessId || typeof businessId !== "string") {
    res.status(400).json({ error: "businessId required" });
    return;
  }
  try {
    const sixMonthsAgo = new Date(Date.now() - 180 * 24 * 60 * 60 * 1e3);
    const reviews = await db.select().from(reviewsTable).where(and(
      eq(reviewsTable.businessId, businessId),
      ne(reviewsTable.status, "pending_video"),
      ne(reviewsTable.status, "pending_review"),
      ne(reviewsTable.status, "pending_verification"),
      ne(reviewsTable.status, "rejected"),
      gte(reviewsTable.createdAt, sixMonthsAgo)
    )).orderBy(desc(reviewsTable.createdAt)).limit(50);
    const userIds = [...new Set(reviews.map((r2) => r2.userId).filter(Boolean))];
    const [trustData, businessRow] = await Promise.all([
      userIds.length > 0 ? db.select({
        id: usersTable.id,
        trustLevel: usersTable.trustLevel,
        identityVerified: usersTable.identityVerified,
        identityVerifiedAt: usersTable.identityVerifiedAt,
        policyViolationsCount: usersTable.policyViolationsCount,
        helpfulReviewsCount: usersTable.helpfulReviewsCount,
        createdAt: usersTable.createdAt,
        reputationScore: usersTable.reputationScore,
        homeCity: usersTable.homeCity,
        isInfluencer: usersTable.isInfluencer
      }).from(usersTable).where(inArray(usersTable.id, userIds)) : Promise.resolve([]),
      db.select({ city: businessesTable.city, state: businessesTable.state }).from(businessesTable).where(eq(businessesTable.id, businessId)).limit(1)
    ]);
    const trustMap = new Map(trustData.map((u2) => [u2.id, {
      level: computeTrustLevel(u2),
      homeCity: u2.homeCity,
      isInfluencer: u2.isInfluencer
    }]));
    const bizCity = businessRow[0]?.city?.toLowerCase().trim() ?? null;
    const bizState = businessRow[0]?.state?.toLowerCase().trim() ?? null;
    const currentUserId = req.user?.id ?? null;
    const enriched = reviews.map((r2) => {
      const td2 = r2.userId ? trustMap.get(r2.userId) : null;
      return {
        ...r2,
        isOwnReview: currentUserId !== null && r2.userId === currentUserId,
        authorTrustLevel: td2?.level ?? 1,
        authorIsInfluencer: td2?.isInfluencer ?? false
      };
    });
    const statsVerified = enriched.filter((r2) => r2.authorTrustLevel >= 2).length;
    const statsInfluencer = enriched.filter((r2) => r2.authorIsInfluencer).length;
    let statsLocal = 0, statsTraveler = 0;
    if (bizCity || bizState) {
      for (const r2 of enriched) {
        const td2 = r2.userId ? trustMap.get(r2.userId) : null;
        const rc2 = td2?.homeCity?.toLowerCase().trim();
        if (!rc2) continue;
        const isLocal = bizCity && rc2.includes(bizCity) || bizState && rc2.includes(bizState);
        if (isLocal) statsLocal++;
        else statsTraveler++;
      }
    }
    const weightedRating = computeWeightedRating(
      enriched.map((r2) => ({ rating: r2.rating, weight: r2.weight ?? "1" }))
    );
    res.json({
      reviews: enriched,
      weightedRating,
      stats: {
        total: enriched.length,
        verified: statsVerified,
        influencer: statsInfluencer,
        local: statsLocal,
        traveler: statsTraveler,
        weightedAverage: weightedRating
      }
    });
  } catch (err) {
    req.log.error({ err }, "Failed to fetch reviews");
    res.status(500).json({ error: "Failed to fetch reviews" });
  }
});
