        verified: r2.verified,
        blackOwned: r2.black_owned,
        ownershipDesignations: r2.ownership_designations ?? [],
        vibes: r2.vibes ?? [],
        hours: r2.hours,
        phone: r2.phone,
        website: r2.website,
        latitude: r2.latitude,
        longitude: r2.longitude,
        hiddenGemLabel: r2.hidden_gem_label,
        hiddenGemTagline: r2.hidden_gem_tagline,
